                  "code": "B2.1.6.1.1",
                  "text": "Use appropriate greetings for special occasions",
                  "exemplar": "Revise daily greetings by having learners identify greeting times in the day: e.g. Morning-Good morning, Afternoon-Good afternoon, Evening-Good evening. Discuss special occasions such as birthdays, anniversaries and festivals. Discuss the correct greetings and responses on these occasions. Let learners take turns to demonstrate greetings for special occasions and also practise the appropriate responses.",
