                  "exemplar": "Introduce the day's topic and show pictures of activities at home. Have learners think-pair-share the domestic activities. Have learners talk about which of the events they like most and why they like them. Have learners role-play some of the scenes. E.g. People engaged in domestic chores. People at table.",
