                  "text": "Write about real or imagined experiences or events using the process approach",
                  "exemplar": "Ask learners simple questions on their daily routines. Let learners brainstorm and choose a topic for the day. e.g. \"A visit to the market\" or \"A visit to the beach\". Using questions, assist learners to write a paragraph or two about their experiences. e.g. i. What is the name of the market? ii. Where is the market? iii. What did you buy from the market? Let learners write a short paragraph and paste it on the notice board. Note: Learners may create imaginary experiences and write about them.",
