                  "code": "B2.5.10.1.1",
                  "text": "Use phonics knowledge to spell words with irregular phonic letter pattern",
                  "exemplar": "Have learners play the pick and spell game to spell phonetically irregular words. e.g. the, face. Have learners use these words in oral and written sentences. Provide sentences with blank spaces for learners to fill in the blanks using the words they have learnt to spell. e.g. i. This is my-------.",
