                  "text": "Read a variety of age and level-appropriate books and texts from print and non-print",
                  "exemplar": "Use the Author's chair to introduce the reading/library time. Have a variety of age and level-appropriate books for learners to make a choice. Introduce narratives, pop-up and flip-the-page texts to learners. Introduce e-books to learners, if available. For each reading session, guide learners to select books.",
