                  "text": "Summarise level-appropriate texts/passages orally",
                  "exemplar": "Learners identify the most important ideas in texts/passages read and restate them in their own words. E.g. Can you retell the story? Who are the main characters? What is the setting? What are the main events? (use herringbone or story map as strategies).",
