                  "text": "Write a short summary of a level-appropriate text/passage read",
                  "exemplar": "Have learners work in groups to write a summary of a text/passage read taking note of the main ideas. Let learners present their write-up for discussion and feedback from the class and teacher.",
                  "resources": null,
                  "keyWords": null,
                  "coreCompetencies": "Communication and collaboration; Reading and Speaking; Personal Development",
                  "assessment": null
