                  "exemplar": "Present a motion to learners. E.g. A lawyer is more important than a doctor. Discuss the meaning and implication of the motion with pupils and invite them to take a stand either for or against the motion. Put learners into two groups: for the motion and against the motion and write down what they think about it. Groups read out their opinions to the class for discussions.",
                  "resources": null,
