                  "exemplar": "Revise all the types of nouns with learners (refer to B1-B5). Provide learners with opportunities to further practice using these nouns. E.g. a. Learners take their reading books and identify and make a list of these nouns, use them in sentences and present their work to the class for feedback. b. Use language drills and games to help learners to practice. e.g. a pair drill for singular/plural nouns: Learner 'A' gives a noun - mango. Learner 'B' gives its plural form 'mangoes' and uses it in a sentence - I love mangoes. Provide further practice activities to build on learners' knowledge on nouns.",
