                  "exemplar": "Learners write on a topic using the simple present, present perfect and past perfect tenses. Discuss the topic with learners contributing with sentences containing the present perfect and past perfect. Let learners write in bits e.g. First start with introduction and guide them to edit. Learners then write a whole essay on a chosen topic individually.",
